import std.io

pub type AppError = Failed(Int64, Int64) | Nope

fn name(r: Result<Int64, AppError>) -> Int64 {
    match r {
        Ok(v) => { return v }
        Err(Nope) => { return -1i64 }
        Err(Failed(a, b)) => { return a * 10i64 + b }
    }
    return 0i64
}

pub fn main() effect io -> Result<(), AppError> {
    io.println("ok ${name(Ok(5i64))}")
    io.println("nope ${name(Err(Nope))}")
    io.println("failed ${name(Err(Failed(1i64, 2i64)))}")
    let bound: Result<Int64, AppError> = Ok(7i64)
    io.println("bound ${name(bound)}")
    let ns = [-3i64, 4i64, 9i64]
    for x in ns {
        if x > 0i64 {
            return Ok(())
        }
        io.println("scan ${x}")
    }
    io.println("unreached")
    return Ok(())
}
